insert into public.member_lessons(lesson_key,module_key,module_title,title,section_order,content,published) values
('metodo-v2-business','m1','Inteligência de mercado','Entenda como a empresa ganha dinheiro',6,'{"how":"Um site só produz valor quando ajuda o negócio a conquistar um resultado. Primeiro identifique o que é vendido, quem compra e como um contato vira cliente. Separe fato publicado, inferência e informação confirmada na conversa. O número de estrelas não revela margem, taxa de fechamento ou faturamento. Critérios de investigação: Serviços que geram receita; Quem provavelmente compra e por qual motivo?; Como o interesse pode se transformar em contrato?; Região e especialidade; Ticket médio ou valor do serviço; Margem e capacidade de atendimento.","steps":["Abra o Google Maps e o site da empresa. Leia as páginas de serviços, a descrição e a área atendida; copie informações concretas.","Leia três avaliações públicas para entender situações que levam alguém a procurar o serviço. Avaliações são pistas, não pesquisa representativa.","Simule o caminho comercial: como o interessado pede orçamento, liga ou agenda? Anote o que é visível e o que precisará perguntar ao dono.","Registre serviços, comprador provável e processo de compra. Se ticket ou margem não estiverem publicados, marque ''a confirmar''; não invente valores."],"example":"Exemplo fictício: uma empresa realiza reformas residenciais. O comprador provavelmente compara portfólio e confiança antes de pedir uma avaliação. A venda pode depender de visita técnica; ainda é preciso confirmar isso com o proprietário.","alternatives":"Não conhece o ticket? Escreva ''a confirmar com o proprietário''. Não sabe quem compra? Consulte três páginas de serviço e duas avaliações antes de formular a hipótese.","output":"Perfil comercial inicial do negócio, com serviços, comprador, processo de compra e dados a confirmar.","verify":"Confirme a entrega correspondente: Serviços que geram receita; Quem provavelmente compra e por qual motivo?; Como o interesse pode se transformar em contrato?. Registre fonte, informação desconhecida e próxima ação. Não considere pesquisa como venda.","trap":"Não confunda hipótese com fato, cliques com contratos ou promessas de receita com resultado medido. Nunca invente números ou declarações atribuídas a um empresário.","instructional_note":"Este conteúdo é o aprofundamento da missão no Fieldwork. Execute o procedimento na área de trabalho, usando informações de uma empresa real."}'::jsonb,true),
('metodo-v2-demand','m1','Inteligência de mercado','Descubra como os compradores chegam até a empresa',7,'{"how":"Antes de recomendar um website, investigue se ele participa da aquisição, da confiança ou da qualificação dos contatos. Uma visita não equivale a um lead. Dados de tráfego, custo e aquisição reais normalmente exigem permissão do proprietário. Critérios de investigação: Onde aparecem sinais de aquisição?; Qual é a provável jornada de compra?; Qual papel o website poderia desempenhar?; Fontes e limites do que foi observado.","steps":["Pesquise no Google o serviço e a cidade como faria um comprador, sem assumir que o primeiro resultado representa todos os clientes.","Visite perfil do Google, website e redes sociais vinculadas. Anote apenas canais observáveis.","Confira se há anúncios públicos na biblioteca de anúncios; um anúncio ativo não prova que a empresa está lucrando.","Desenhe em uma frase o caminho provável desde descobrir a empresa até solicitar atendimento. Marque as partes desconhecidas para validar na conversa."],"example":"Exemplo fictício: a empresa publica antes/depois no Instagram e oferece agendamento no site. Isso sugere uma jornada de comparação e confiança, não comprova quantos leads chegam por cada canal.","alternatives":"Se não encontrar anúncios, não conclua que a empresa não anuncia. Continue com o Google, site e fontes públicas. O dono confirmará os canais reais.","output":"Mapa preliminar de canais de aquisição e jornada do comprador, separando canais observáveis de desconhecidos.","verify":"Confirme a entrega correspondente: Onde aparecem sinais de aquisição?; Qual é a provável jornada de compra?; Qual papel o website poderia desempenhar?. Registre fonte, informação desconhecida e próxima ação. Não considere pesquisa como venda.","trap":"Não confunda hipótese com fato, cliques com contratos ou promessas de receita com resultado medido. Nunca invente números ou declarações atribuídas a um empresário.","instructional_note":"Este conteúdo é o aprofundamento da missão no Fieldwork. Execute o procedimento na área de trabalho, usando informações de uma empresa real."}'::jsonb,true),
('metodo-v2-goal','offers','Ofertas e psicologia de compra','Defina o resultado comercial que o website deveria apoiar',7,'{"how":"A estratégia começa pelo resultado desejado, não por um layout. O website deve facilitar uma decisão comercial específica. O resultado é uma hipótese operacional, a confirmar com o decisor. Medir cliques não prova vendas; atribuição, qualidade dos leads e fechamento também importam. Critérios de investigação: Resultado comercial prioritário (hipótese); O que seria um contato de qualidade?; Jornada desejada do visitante; O que mediríamos, com autorização?.","steps":["Use os serviços e o comprador encontrados antes para escolher UMA ação comercial prioritária: orçamento, chamada, agendamento, reserva ou venda.","Descreva o que caracteriza um contato qualificado e por que ele teria valor para a empresa.","Trace o caminho ideal do visitante do primeiro contato até essa ação, com os menores obstáculos razoáveis.","Escolha uma medida possível para validar o resultado mais tarde e marque como hipótese tudo que não foi confirmado com o dono."],"example":"Uma clínica pode priorizar agendamentos; um serviço emergencial, chamadas; uma empresa de reformas, pedidos qualificados. Não existe um CTA universal para todo negócio.","alternatives":"Se houver muitos objetivos, escolha o mais próximo da receita que o website consegue influenciar e registre os secundários para depois.","output":"Objetivo comercial principal do website, definição de contato qualificado e métrica possível.","verify":"Confirme a entrega correspondente: Resultado comercial prioritário (hipótese); O que seria um contato de qualidade?; Jornada desejada do visitante. Registre fonte, informação desconhecida e próxima ação. Não considere pesquisa como venda.","trap":"Não confunda hipótese com fato, cliques com contratos ou promessas de receita com resultado medido. Nunca invente números ou declarações atribuídas a um empresário.","instructional_note":"Este conteúdo é o aprofundamento da missão no Fieldwork. Execute o procedimento na área de trabalho, usando informações de uma empresa real."}'::jsonb,true),
('metodo-v2-blueprint','m4','Diagnóstico e auditoria','Desenhe a referência de um site intencional',6,'{"how":"Sem uma referência ligada ao objetivo comercial, qualquer opinião estética parece um defeito. Agora projete o que deveria facilitar a jornada. Uma marca antiga não é automaticamente ruim. Cada elemento visual deve ser avaliado pelo papel que cumpre no público, no contexto e na jornada, não pela preferência do designer. Critérios de investigação: Mensagem e proposta de valor desejadas; Sequência sugerida de seções e motivo; Copy, provas e objeções a tratar; Identidade visual, logo, tipografia e coerência; Ação principal e fluxo até ela; Como testar e medir depois.","steps":["Escreva o serviço, a região e a promessa que precisam ficar claros na primeira tela.","Ordene as seções conforme as dúvidas do comprador: serviço, provas, processo, objeções, contato. Justifique essa ordem.","Defina o papel de fotos, cores, tipografia, identidade e logotipo: confiança, legibilidade, diferenciação e coerência, não gosto pessoal.","Descreva CTAs, prova verificável, mobile, formulário e eventos a medir. Faça um esboço no papel, Figma ou no próprio registro."],"example":"Referência hipotética para remodeling: hero que comunica serviço e cidade, portfólio de projetos reais, processo, prova e formulário de orçamento qualificado. A ordem deve ser testada; não é uma receita imutável.","alternatives":"Não sabe desenhar? Faça uma lista das seções no papel. Descreva em uma frase por que cada uma ajuda o comprador. Não é necessário abrir o Figma.","output":"Mapa de conversão ideal: posicionamento, ordem das seções, persuasão, identidade visual, CTAs e mensuração.","verify":"Confirme a entrega correspondente: Mensagem e proposta de valor desejadas; Sequência sugerida de seções e motivo; Copy, provas e objeções a tratar; Identidade visual, logo, tipografia e coerência; Ação principal e fluxo até ela. Registre fonte, informação desconhecida e próxima ação. Não considere pesquisa como venda.","trap":"Não confunda hipótese com fato, cliques com contratos ou promessas de receita com resultado medido. Nunca invente números ou declarações atribuídas a um empresário.","instructional_note":"Este conteúdo é o aprofundamento da missão no Fieldwork. Execute o procedimento na área de trabalho, usando informações de uma empresa real."}'::jsonb,true),
('metodo-v2-diagnose','m4','Diagnóstico e auditoria','Compare o site atual com a estratégia ideal',7,'{"how":"O objetivo não é colecionar defeitos; é descobrir diferenças entre o que o negócio precisa e o que a experiência atual pode estar oferecendo. Uma auditoria visual não prova queda de conversão. Para desempenho use métricas adequadas; para negócios reais confirme dados com o proprietário. Critérios de investigação: O que o website atual está fazendo?; Diferença relevante em relação ao objetivo comercial; Evidência verificável ou limite da análise; O que já funciona bem?; Classificação do achado.","steps":["Abra a home e uma página de serviço no celular. Faça o percurso real até a ação principal, sem enviar formulários de terceiros.","Compare objetivo, clareza da mensagem, identidade, ordem das seções, provas, CTA, velocidade e uso mobile com a referência anterior.","Registre um comportamento observável com URL, dispositivo e contexto; documente o que já funciona bem.","Use PageSpeed Insights se houver uma questão técnica. Separe problema reproduzido, oportunidade hipotética e impacto medido."],"example":"Observação: botão de orçamento pouco visível numa página de serviço. Hipótese: visitantes motivados podem ter dificuldade para iniciar contato. Não afirmar perda financeira sem dados.","alternatives":"Se o website estiver bom, registre isso. Investigue oferta, tráfego ou atendimento, ou descarte a oportunidade de website em vez de inventar defeitos.","output":"Diagnóstico comparativo entre website atual e jornada ideal, com fatos, hipóteses e pontos fortes.","verify":"Confirme a entrega correspondente: O que o website atual está fazendo?; Diferença relevante em relação ao objetivo comercial; Evidência verificável ou limite da análise; Classificação do achado. Registre fonte, informação desconhecida e próxima ação. Não considere pesquisa como venda.","trap":"Não confunda hipótese com fato, cliques com contratos ou promessas de receita com resultado medido. Nunca invente números ou declarações atribuídas a um empresário.","instructional_note":"Este conteúdo é o aprofundamento da missão no Fieldwork. Execute o procedimento na área de trabalho, usando informações de uma empresa real."}'::jsonb,true),
('metodo-v2-opportunity','offers','Ofertas e psicologia de compra','Transforme o diagnóstico em uma hipótese de crescimento',8,'{"how":"O valor não é um botão novo: é a possibilidade de facilitar mais contatos qualificados, reservas ou vendas, se o problema existir e tiver prioridade para o empresário. Separe oferta de site novo, redesign estratégico e otimização de jornada. A recomendação depende do problema comercial real e da capacidade de implementar e mensurar. Critérios de investigação: Qual oportunidade comercial pode existir?; Que experiência ou website estratégico construiríamos?; Por que isso poderia ajudar e qual é a incerteza?; O que confirmar com o empresário?.","steps":["Escolha uma diferença que seja importante para a intenção de compra, com evidência ou hipótese identificada.","Descreva a experiência ou website estratégico que proporia para atender ao objetivo, em vez de uma lista de consertos soltos.","Explique o ganho potencial sem inventar receita ou porcentagens. Se quiser simular cenários, identifique-os como hipotéticos.","Registre o que precisa ser confirmado com o proprietário para saber se há demanda e orçamento."],"example":"Não vendemos uma troca de cor. Investigamos se uma experiência estratégica pode transformar mais interesse em oportunidades qualificadas.","alternatives":"Se não houver sinal plausível, registre ''sem oportunidade demonstrável agora'' e siga para outro prospect. Isso é um resultado válido.","output":"Tese de oportunidade comercial plausível e produto digital proposto, com dúvidas a validar com o decisor.","verify":"Confirme a entrega correspondente: Qual oportunidade comercial pode existir?; Que experiência ou website estratégico construiríamos?; Por que isso poderia ajudar e qual é a incerteza?. Registre fonte, informação desconhecida e próxima ação. Não considere pesquisa como venda.","trap":"Não confunda hipótese com fato, cliques com contratos ou promessas de receita com resultado medido. Nunca invente números ou declarações atribuídas a um empresário.","instructional_note":"Este conteúdo é o aprofundamento da missão no Fieldwork. Execute o procedimento na área de trabalho, usando informações de uma empresa real."}'::jsonb,true),
('metodo-v2-outreach','m2','Prospecção e aquisição','Converse sobre resultado, não sobre conserto',9,'{"how":"O primeiro contato precisa descobrir se o empresário valoriza a oportunidade. Não pressupomos que ele queira um novo website. Vendas B2B exigem diagnóstico, não promessas de mais faturamento sem dados. Para e-mail nos EUA, considere os requisitos aplicáveis do CAN-SPAM. Critérios de investigação: Canal e contato profissional; Mensagem de abordagem preparada; Estado real do contato; Próxima ação e data combinada.","steps":["Confirme nome da empresa, canal profissional público e o detalhe observado que justifica o contato.","Escreva uma mensagem curta em inglês: contexto, oportunidade plausível, pergunta sobre prioridade e convite pequeno.","Envie pelo canal apropriado, respeitando regras de comunicação comercial e pedidos de não contato.","Registre se foi enviado, quando retomar e o resultado; salvar rascunho não significa contato realizado."],"example":"Hi Mark, I was looking at how homeowners request kitchen remodeling estimates. I noticed a possible opportunity to make that path more intentional on your website. Is improving qualified inquiries a priority this quarter?","alternatives":"Não tem nome do proprietário? Use o contato comercial público e não finja familiaridade. Sem envio, salve como rascunho e não registre a etapa como contato feito.","output":"Mensagem de abertura, canal, status real do envio e próximo compromisso.","verify":"Confirme a entrega correspondente: Canal e contato profissional; Mensagem de abordagem preparada; Estado real do contato. Registre fonte, informação desconhecida e próxima ação. Não considere pesquisa como venda.","trap":"Não confunda hipótese com fato, cliques com contratos ou promessas de receita com resultado medido. Nunca invente números ou declarações atribuídas a um empresário.","instructional_note":"Este conteúdo é o aprofundamento da missão no Fieldwork. Execute o procedimento na área de trabalho, usando informações de uma empresa real."}'::jsonb,true),
('metodo-v2-discovery','m3','Comunicação e vendas','Confirme a prioridade com o proprietário',6,'{"how":"Oportunidade técnica não é necessidade comercial confirmada. Precisamos ouvir como o negócio funciona e o que o empresário quer melhorar. Descoberta comercial: situação, dor declarada, impacto relatado, prioridade, objeção, decisor e critério de compra. Pergunte e ouça antes de argumentar. Critérios de investigação: O que o proprietário confirmou?; Prioridade, urgência e razão; Decisor, investimento e prazo; Próxima decisão combinada.","steps":["Proponha uma conversa de 15 minutos e explique que quer entender aquisição, atendimento e objetivos antes de recomendar um site.","Pergunte de onde vêm os melhores contatos, o que já funciona, quais contatos não viram negócio e por quê.","Confirme qual resultado seria valioso, a prioridade, o prazo, o decisor e a faixa de investimento, sem forçar respostas.","Resuma o que realmente foi dito e combine uma próxima decisão. Se ainda não conversaram, registre ''a confirmar'' e não marque como validado."],"example":"“You mentioned that most website inquiries are too broad. Which project details would make an inquiry useful for your team?” Essa pergunta descobre a necessidade, sem empurrar uma solução pré-fabricada.","alternatives":"Se a pessoa não respondeu, não invente a conversa. Agende o acompanhamento no CRM e continue outro prospect.","output":"Resumo literal da prioridade do proprietário, decisor, orçamento/prazo conhecidos e próximo passo.","verify":"Confirme a entrega correspondente: O que o proprietário confirmou?; Prioridade, urgência e razão; Decisor, investimento e prazo; Próxima decisão combinada. Registre fonte, informação desconhecida e próxima ação. Não considere pesquisa como venda.","trap":"Não confunda hipótese com fato, cliques com contratos ou promessas de receita com resultado medido. Nunca invente números ou declarações atribuídas a um empresário.","instructional_note":"Este conteúdo é o aprofundamento da missão no Fieldwork. Execute o procedimento na área de trabalho, usando informações de uma empresa real."}'::jsonb,true),
('metodo-v2-offer','offers','Ofertas e psicologia de compra','Crie uma proposta de website estratégico',9,'{"how":"A proposta conecta o objetivo declarado pelo empresário a uma experiência digital planejada, um escopo claro e critérios verificáveis. Venda de resultado desejado não equivale à garantia de resultado. Diferencie resultado contratado (site funcional) de indicadores a monitorar após publicação. Critérios de investigação: Resultado comercial que a proposta pretende apoiar; Website e entregas estratégicas; Investimento e prazo (não invente); Como validar entrega e acompanhar resultado.","steps":["Comece pelo problema comercial confirmado e pela intenção de compra que o site deve apoiar.","Descreva a solução completa: posicionamento, copy, hierarquia, provas reais, navegação, CTA, mobile e mensuração conforme o escopo.","Defina entregáveis, exclusões, revisões, responsabilidade do cliente, prazo, investimento e condições de pagamento.","Revise com o cliente; não prometa leads ou faturamento garantidos. Salve a proposta no módulo comercial quando estiver validada."],"example":"“Conversion-focused website for qualified remodeling estimate inquiries”: escopo transparente, estratégia de provas e processo, rastreamento de formulários, preço e dependências.","alternatives":"Se não consegue precificar, liste horas e custos, estime revisões e defina o menor escopo sustentável. Consulte o Blue Book antes de prometer prazo.","output":"Proposta de website estratégico com objetivo, escopo, preço/condições e indicadores de acompanhamento.","verify":"Confirme a entrega correspondente: Resultado comercial que a proposta pretende apoiar; Website e entregas estratégicas; Investimento e prazo (não invente); Como validar entrega e acompanhar resultado. Registre fonte, informação desconhecida e próxima ação. Não considere pesquisa como venda.","trap":"Não confunda hipótese com fato, cliques com contratos ou promessas de receita com resultado medido. Nunca invente números ou declarações atribuídas a um empresário.","instructional_note":"Este conteúdo é o aprofundamento da missão no Fieldwork. Execute o procedimento na área de trabalho, usando informações de uma empresa real."}'::jsonb,true),
('metodo-v2-close','m3','Comunicação e vendas','Conduza a decisão e registre o resultado real',7,'{"how":"Uma proposta só vira contrato quando há aceite verdadeiro. Acompanhar com respeito e medir a operação fecha o ciclo de aprendizagem. O funil mede empresas únicas, contatos, respostas, reuniões, propostas, contratos e entradas. Calcule taxas apenas com dados registrados. Critérios de investigação: O que o prospect decidiu ou respondeu?; Próximo compromisso e prazo; O que este caso ensinou para a próxima venda?.","steps":["Revise se o decisor recebeu e compreendeu escopo, preço, prazo e resultado pretendido.","Registre a objeção nas palavras do cliente; esclareça riscos, sem desconto automático ou urgência fictícia.","Combine próximo passo com data. Só marque ''Contrato'' no CRM depois de aceite real; confirme entrada recebida separadamente.","Atualize o que aprendeu, examine conversas em aberto e escolha o próximo prospect. Missões não dependem da virada do dia."],"example":"Negociação real: o cliente aceita o escopo, assina e paga a entrada. Registre contrato e pagamento como eventos diferentes, sem transformar uma conversa positiva em venda.","alternatives":"Se a proposta foi recusada, registre o motivo conhecido e escolha outro prospect. Se não houver resposta, programe follow-up útil, não pressão.","output":"Decisão real, próximo compromisso e aprendizado do funil, distinguindo contrato de depósito.","verify":"Confirme a entrega correspondente: O que o prospect decidiu ou respondeu?; Próximo compromisso e prazo; O que este caso ensinou para a próxima venda?. Registre fonte, informação desconhecida e próxima ação. Não considere pesquisa como venda.","trap":"Não confunda hipótese com fato, cliques com contratos ou promessas de receita com resultado medido. Nunca invente números ou declarações atribuídas a um empresário.","instructional_note":"Este conteúdo é o aprofundamento da missão no Fieldwork. Execute o procedimento na área de trabalho, usando informações de uma empresa real."}'::jsonb,true)
